// Input: {echo_us: 880}
var echoUs = Number(msg.payload.echo_us);

// Speed of sound at 16°C = 340.9 m/s = 0.03409 cm/µs
// distance = (echo_us * speed) / 2
var speedCmPerUs = 0.03409;
var distance_cm = (echoUs * speedCmPerUs) / 2;

// Piecewise linear volume
var volume;
if (distance_cm >= 16.30) {
    volume = 0;
} else if (distance_cm >= 15.98) {
    volume = (16.30 - distance_cm) / (16.30 - 15.98) * 100;
} else if (distance_cm >= 5.13) {
    volume = 100 + (15.98 - distance_cm) / (15.98 - 5.13) * 900;
} else {
    volume = 1000;
}

msg.payload = {
    echo_us: echoUs,
    distance_cm: Math.round(distance_cm * 100) / 100,
    volume_ml: Math.round(volume * 100) / 100
};

return msg;
